  <div class="brand"><span class="mark"><svg class="potato-logo" viewBox="0 0 32 32" aria-hidden="true"><path fill="#8d5d2e" d="M8 5c5-4 14-2 17 4 3 7 0 17-7 19-7 2-14-1-16-8C0 13 3 8 8 5Z"/><path fill="#d9a15b" d="M9 7c4-3 11-2 14 3 2 5 0 13-5 15-5 2-11-1-12-6-2-5-1-9 3-12Z"/><circle cx="12" cy="14" r="1.5" fill="#332318"/><circle cx="21" cy="13" r="1.5" fill="#332318"/><path d="M13 19c2 2 5 2 7 0" fill="none" stroke="#332318" stroke-width="1.5" stroke-linecap="round"/></svg></span><span>Potato</span></div>
